PYTHONPATH=/home/etudiantelambda/.local/lib/python3.12/site-packages python3 << 'EOF'
from scapy.all import *

pkts = rdpcap('capture.pcapng')

# Trouver les paquets TLS (port 443 ou 4433)
for i, pkt in enumerate(pkts):
    if TCP in pkt:
        sport = pkt[TCP].sport
        dport = pkt[TCP].dport
        if sport == 443 or dport == 443 or sport == 4433 or dport == 4433:
            print(f"Paquet {i}: sport={sport}, dport={dport}, payload={len(pkt[TCP].payload)} bytes")
            if Raw in pkt:
                print(f"  Raw data: {bytes(pkt[Raw])[:50]}")
EOF
